router.get("/", (req, res) => {
  const todos = db.prepare("SELECT * FROM todos WHERE user_id = ?").all(req.userId);
  res.json(todos);
});

router.post("/", (req, res) => {
  const { title } = req.body;
  const result = db.prepare("INSERT INTO todos (user_id, title) VALUES (?, ?)").run(req.userId, title);
  res.status(201).json({ id: result.lastInsertRowid, title, done: 0 });
});
